INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28901, 'Hebrews 5:4', 'Hebrews', 5, 4, '&nbsp;او هيڅوک هم په خپله د اِمامت دا عزت نۀ شى حاصلولے خو صرف د خُدائ پاک په مرضۍ يې حاصلولے شى لکه څنګه چې هارون حاصل کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28902, 'Hebrews 5:5', 'Hebrews', 5, 5, '&nbsp;دغه شان مسيح هم د مشر اِمام عزت پخپله حاصل نۀ کړو بلکې هغه، هغه چا منتخب کړو چا چې ورته فرمائيلى وُو چې، ”تۀ زما زوئ يې او د نن نه زۀ ستا پلار شوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28903, 'Hebrews 5:6', 'Hebrews', 5, 6, '&nbsp;لکه څنګه چې هغه په بل ځائ کښې فرمائى چې، ”تۀ د مَلِک‌صِدق په شان تل تر تله اِمام يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28904, 'Hebrews 5:7', 'Hebrews', 5, 7, '&nbsp;کله چې عيسىٰ په زمکه ژوند تېرولو نو په هغه ورځو کښې هغۀ په چغو او اوښکو بهېدلو سره خُدائ پاک ته دُعا او مِنت زارى وکړه چا چې هغه د مرګ نه بچ کولے شو، او د هغۀ دُعا قبوله شوه ځکه چې هغۀ په پوره توګه خپل ځان خُدائ پاک ته وقف کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28905, 'Hebrews 5:8', 'Hebrews', 5, 8, '&nbsp;اګر چې هغه زوئ وو، خو د تکليفونو په تېرولو هغۀ فرمانبردارى زده کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28906, 'Hebrews 5:9', 'Hebrews', 5, 9, '&nbsp;نو چې هغه کامِل کړے شو نو هغه د خپلو ټولو منونکو دپاره د ابدى خلاصون وسيله وګرځېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28907, 'Hebrews 5:10', 'Hebrews', 5, 10, '&nbsp;او هغۀ د خُدائ پاک د طرفه د مَلِک‌صِدق په شان مشر اِمام منتخب شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28908, 'Hebrews 5:11', 'Hebrews', 5, 11, '&nbsp;په دې حقله مونږ سره ډيرې خبرې دى خو دا تشريح کول سخت کار دے، ځکه چې تاسو په پوهېدو کښې سست يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28909, 'Hebrews 5:12', 'Hebrews', 5, 12, '&nbsp;نو په دې وخت کښې خو تاسو له اُستاذان کېدل په کار وُو، خو تاسو ته د يو کس ضرورت دے چې د خُدائ پاک د کلام بنيادى اصُول بيا در زده کړى، نو تاسو ته د ماشوم په شان د پيو ضرورت دے نه چې د سخت خوراک.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28910, 'Hebrews 5:13', 'Hebrews', 5, 13, '&nbsp;ځکه هر څوک چې پئ څښى، هغه لا ماشوم وى او د صداقت د کلام تجربه يې نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28911, 'Hebrews 5:14', 'Hebrews', 5, 14, '&nbsp;خو سخت خوراک د بالغه کسانو دپاره وى ځکه چې هغوئ په تجربې سره د ښۀ او بد تر مينځه فرق کولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28912, 'Hebrews 6:1', 'Hebrews', 6, 1, '&nbsp;نو راځئ چې د مسيح په حقله د ابتدائى تعليم خبرې پرېږدو او د بلوغيت په طرف قدم اوچت کړُو. مونږ ته د دې ابتدائى کارونو د بار بار کولو ضرورت نشته لکه د شرارت اميز عملونو نه توبه کول او په خُدائ پاک ايمان راوړل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28913, 'Hebrews 6:2', 'Hebrews', 6, 2, '&nbsp;او تاسو ته نور د بپتسمو او لاس کېښودلو او د مړو نه د بيا ژوندى کېدلو او د تل عدالت په حقله د تعليم ورکولو ضرورت نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28914, 'Hebrews 6:3', 'Hebrews', 6, 3, '&nbsp;او کۀ د خُدائ پاک رضا وى نو مونږ به هم دغه کارونه کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28915, 'Hebrews 6:4', 'Hebrews', 6, 4, '&nbsp;ځکه چې هغوئ ته دا ناممکنه ده چې بيا توبې ويستلو ته جوړ شى څوک چې يو ځل رڼا ته راغلى وى، او د آسمانى نعمتونو خوند يې اخستے وى، او په روحُ القُدس کښې شريک شوى وى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28916, 'Hebrews 6:5', 'Hebrews', 6, 5, '&nbsp;او چې د خُدائ پاک د کلام نېکى او د راتلونکى زمانې د قوتونو مزه يې اخستى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28917, 'Hebrews 6:6', 'Hebrews', 6, 6, '&nbsp;او څوک چې د خُدائ پاک نه واوړى نو دا ناممکنه ده چې څوک هغوئ بيا توبه ويستلو ته راواړوى نو ځکه چې هغوئ په خپله د خُدائ پاک زوئ په دوېم ځل په سولۍ کوى او په خلقو کښې يې شرموى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28918, 'Hebrews 6:7', 'Hebrews', 6, 7, '&nbsp;هغه زمکه چې د باران په اوبو سيرابه شى کوم چې په هغې مسلسل وريږى او د هغوئ دپاره ښۀ فصل پېدا کوى څوک چې په هغې کښې کرونده کوى، نو هغه زمکه د خُدائ پاک د طرفه برکت مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28919, 'Hebrews 6:8', 'Hebrews', 6, 8, '&nbsp;خو کۀ دا زمکه ازغى او جاړې زرغونوى نو دا بې‌فائدې ده او زر به لعنتى شى او د دې اَنجام به سوزول وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28920, 'Hebrews 6:9', 'Hebrews', 6, 9, '&nbsp;ګرانو دوستانو، اګر چې مونږ ستاسو په حقله داسې خبرې کوُو خو مونږ په دې باور نۀ يُو چې دا به ستاسو په حقله وى. مونږ په دې خبره مطمئن يُو چې د خلاصون نه به ښۀ مېوه تاسو ته مِلاو شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28921, 'Hebrews 6:10', 'Hebrews', 6, 10, '&nbsp;ځکه چې خُدائ پاک بې‌اِنصافه نۀ دے، هغه به ستاسو کار او هغه مينه هېره نۀ کړى چې د هغۀ د نوم د خاطره مو د مقدسينو په خِدمت کولو کښې څرګنده کړه او اوس يې هم کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28922, 'Hebrews 6:11', 'Hebrews', 6, 11, '&nbsp;او مونږ دا غواړو چې په تاسو کښې دې هر يو په پوره اُميد سره تر آخره هم دغه شان کوشش کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28923, 'Hebrews 6:12', 'Hebrews', 6, 12, '&nbsp;نو د دې دپاره چې تاسو سست نۀ شئ بلکې د هغوئ په نقش قدم شئ څوک چې د ايمان او صبر په وسيله د لوظ وارثان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28924, 'Hebrews 6:13', 'Hebrews', 6, 13, '&nbsp;کله چې خُدائ پاک د اِبراهيم سره لوظ وکړو نو د هغۀ نه بل څوک لوئ نۀ وو چې قسم يې پرې کړے وے نو ځکه هغۀ په خپل نوم قسم وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28925, 'Hebrews 6:14', 'Hebrews', 6, 14, '&nbsp;هغۀ وفرمائيل چې، ”زۀ به تا له په رښتيا په برکتونو برکتونه درکوم او ستا اولاد به ډېر زياتوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28926, 'Hebrews 6:15', 'Hebrews', 6, 15, '&nbsp;او دغه شان اِبراهيم په صبر کولو هغه لوظ حاصل کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28927, 'Hebrews 6:16', 'Hebrews', 6, 16, '&nbsp;انسانان يقيناً چې د خپل ځان نه په لوئ څيز قسم خورى او د هغوئ د هر يو بحث آخرى ثبوت د قسم سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28928, 'Hebrews 6:17', 'Hebrews', 6, 17, '&nbsp;هم په دې طريقه کله چې خُدائ پاک وغوښتل چې د وعدې وارثانو ته خپل هغه نۀ بدلېدونکے مقصد نور هم روښانه کړى، نو هغۀ د دې د ضمانت دپاره قسم هم وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28929, 'Hebrews 6:18', 'Hebrews', 6, 18, '&nbsp;نو د دې دواړو نۀ بدلېدونکو خبرو په وجه دا ناممکنه ده چې خُدائ پاک غلط ثابت شى، او مونږ چا چې په هغۀ کښې پناه اخستې ده نو مونږ دې په ډېره زړۀ ورتيا سره هغه اُميد راټينګ کړُو چې زمونږ په وړاندې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28930, 'Hebrews 6:19', 'Hebrews', 6, 19, '&nbsp;دا زمونږ اُميد دے او دا زمونږ د ژوند دپاره رښتينے او مضبوط لنګر دے او دا داسې اُميد دے چې د پړدې دننه مقدس مقام ته رسېدلے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28931, 'Hebrews 6:20', 'Hebrews', 6, 20, '&nbsp;چرته چې عيسىٰ زمونږ نه وړاندې زمونږ دپاره لاړو او د تل دپاره د مَلِک‌صِدق په شان مشر اِمام جوړ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28932, 'Hebrews 7:1', 'Hebrews', 7, 1, '&nbsp;مَلِک‌صِدق، د شاليم بادشاه او د خُدائ تعالىٰ يو اِمام وو. اِبراهيم چې بادشاهانو له د ماتې ورکولو نه واپس راتلو نو مَلِک‌صِدق سره مِلاو شو نو هغۀ اِبراهيم له برکت ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28933, 'Hebrews 7:2', 'Hebrews', 7, 2, '&nbsp;او بيا هغۀ ته اِبراهيم د غنيمت لسمه حِصه ورکړه. مَلِک‌صِدق د نوم معنىٰ ”د صداقت بادشاه ده“ او د شاليم بادشاه معنىٰ ”د صُلح بادشاه ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28934, 'Hebrews 7:3', 'Hebrews', 7, 3, '&nbsp;هغه بې‌پلاره، بې‌موره، او بې‌نسب‌نامې دے. او نۀ د هغۀ د ژوند شروع او نۀ آخر شته، خو د خُدائ پاک د زوئ په شان هغه تل تر تله اِمام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28935, 'Hebrews 7:4', 'Hebrews', 7, 4, '&nbsp;وګورئ هغه څومره عظيم انسان وو تر دې چې د قوم نيکۀ اِبراهيم ورته د غنيمت د مال لسمه حِصه ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28936, 'Hebrews 7:5', 'Hebrews', 7, 5, '&nbsp;او هر څوک چې د ليوى اولاد وى هغوئ ته به اِمامت ملاويږى او په شريعت کښې هغوئ ته دا حکم دے چې د هغه خلقو نه چې د هغوئ د خپل قوم نه دى هم لسمه حِصه راغونډه کړى، کۀ څۀ هم چې هغوئ د اِبراهيم اولاد هم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28937, 'Hebrews 7:6', 'Hebrews', 7, 6, '&nbsp;خو مَلِک‌صِدق د هغوئ د نسب نه جدا وو، هغۀ د اِبراهيم نه هم لسمه حِصه راغونډه کړه او مَلِک‌صِدق اِبراهيم له برکت ورکړو چا سره چې خُدائ پاک د مخکښې نه وعده کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28938, 'Hebrews 7:7', 'Hebrews', 7, 7, '&nbsp;په دې کښې د بحث خبره نشته چې ورکوټے د لوئ نه برکت مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28939, 'Hebrews 7:8', 'Hebrews', 7, 8, '&nbsp;او هغه اِمامان څوک چې لسمه حِصه راټولوى انسانان دى څوک چې مړ کېدونکى دى، خو مَلِک‌صِدق د هغوئ نه لوئ دے، ځکه چې مونږ ته وئيلے شوى دى چې هغه ژوندے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28940, 'Hebrews 7:9', 'Hebrews', 7, 9, '&nbsp;نو مونږ دا وئيلے شُو چې ليوى څوک چې لسمه حِصه راټولوى هغۀ په خپله د اِبراهيم په وسيله لسمه حِصه ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28941, 'Hebrews 7:10', 'Hebrews', 7, 10, '&nbsp;ځکه کله چې مَلِک‌صِدق د اِبراهيم سره مِلاو شو نو ليوى لا د خپل نيکۀ اِبراهيم په وجود کښې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28942, 'Hebrews 7:11', 'Hebrews', 7, 11, '&nbsp;نو بيا کۀ د ليوى اِمامانو په طريقه خلقو ته شريعت ورکړے شو او د هغوئ د طريقې په مطابق خلق کامِل کېدے شول نو بيا د دې خبرې څۀ حاجت وو چې بل اِمام يعنې مَلِک‌صِدق دې د هارون په ځائ مقرر کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28943, 'Hebrews 7:12', 'Hebrews', 7, 12, '&nbsp;ځکه کله چې په اِمامت کښې بدلون راشى نو بيا دا هم ضرورى وى چې شريعت هم بدل کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28944, 'Hebrews 7:13', 'Hebrews', 7, 13, '&nbsp;نو چې د چا په حقله چې دا خبرې کيږى، هغه د بلې قبيلې دے د کومې نه چې کله هم چا د قربان‌ګاه خِدمت نۀ دے کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28945, 'Hebrews 7:14', 'Hebrews', 7, 14, '&nbsp;ځکه چې دا ښکاره خبره ده چې زمونږ مالِک د يهوداه د قبيلې نه پېدا شو او د دې قبيلې په حقله موسىٰ د اِمامت هيڅ ذکر نۀ دے کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28946, 'Hebrews 7:15', 'Hebrews', 7, 15, '&nbsp;دا خبره نوره هم صفا شوه د کله نه چې يو بل اِمام، لکه د مَلِک‌صِدق په شان راښکاره شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28947, 'Hebrews 7:16', 'Hebrews', 7, 16, '&nbsp;څوک چې د نسبى اصُولو په مطابق نه، بلکې د غېر فانى ژوندون د قوت په مطابق اِمام مقرر شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28948, 'Hebrews 7:17', 'Hebrews', 7, 17, '&nbsp;ځکه چې د هغۀ په حق کښې دا تصديق شوے دے چې، ”تۀ به د مَلِک‌صِدق په شان تل تر تله اِمام يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28949, 'Hebrews 7:18', 'Hebrews', 7, 18, '&nbsp;غرض دا چې اولنى احکام يو طرف ته کړے شول ځکه چې دا کمزورى او بې‌کاره وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28950, 'Hebrews 7:19', 'Hebrews', 7, 19, '&nbsp;ځکه چې شريعت هيڅ څيز کامِل کړے نۀ دے، او د هغې په ځائ يو قوى اُميد جوړ کړے شو چې د هغۀ په وسيله مونږ خُدائ پاک ته نزدې ورتلے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28951, 'Hebrews 7:20', 'Hebrews', 7, 20, '&nbsp;د هغۀ تصديق د قسم سره وشو. نور اِمامان بغېر د قَسم نه مقرر شوى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28952, 'Hebrews 7:21', 'Hebrews', 7, 21, '&nbsp;خو عيسىٰ په قَسم سره اِمام مقرر کړے شو ځکه چې خُدائ پاک په خپله هغۀ ته وفرمائيل چې، ”مالِک قَسم وخوړو او هغه به د دې نه وروستو نۀ شى چې تۀ به د تل دپاره اِمام يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28953, 'Hebrews 7:22', 'Hebrews', 7, 22, '&nbsp;هم د دې قسم په وجه عيسىٰ د يوې قوى وعدې ضامن شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28954, 'Hebrews 7:23', 'Hebrews', 7, 23, '&nbsp;پخوا د رِواج په مطابق د اِمامانو شمېر زيات وو ځکه چې مرګ هغوئ د خدمت کولو په عُهده قائم پرې نۀ ښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28955, 'Hebrews 7:24', 'Hebrews', 7, 24, '&nbsp;خو د عيسىٰ اِمامت ابدى دے ځکه چې هغه تل تر تله ژوندے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28956, 'Hebrews 7:25', 'Hebrews', 7, 25, '&nbsp;نو په دې وجه هغه اوس او همېشه کولے شى چې څوک هم د هغۀ په وسيله خُدائ پاک ته راځى هغه هغوئ ته خلاصون ورکولے شى ځکه چې هغه د هغوئ د شفاعت دپاره همېشه ژوندے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28957, 'Hebrews 7:26', 'Hebrews', 7, 26, '&nbsp;ځکه چې مونږ ته هم د داسې مشر اِمام ضرورت دے چې هغه پاک او معصوم او بې‌داغه وى، او د ګناهګارانو نه جدا او د آسمانونو نه اوچت وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28958, 'Hebrews 7:27', 'Hebrews', 7, 27, '&nbsp;او هغه دې د نورو مشرانو اِمامانو په شان د دې محتاج نۀ وى چې هره ورځ اول د خپلو ګناهونو دپاره او بيا د اُمت د ګناهونو دپاره قربانۍ ورکوى ځکه چې دا کار هغۀ په يو ځل د ټولو دپاره وکړو کله چې يې خپل ځان قربان کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28959, 'Hebrews 7:28', 'Hebrews', 7, 28, '&nbsp;نو شريعت داسې خلق مشران اِمامان مقرروى چې کمزورى وى، خو د شريعت نه وروستو خُدائ پاک خپل زوئ په قَسم خوړلو سره اِمام مقرر کړو، څوک چې د تل دپاره کامِل کړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28960, 'Hebrews 8:1', 'Hebrews', 8, 1, '&nbsp;اوس چې کومې خبرې مونږ کوُو په هغې کښې د ټولو نه اهمه خبره دا ده چې زمونږ يو داسې مشر اِمام دے څوک چې په آسمانونو کښې د قادر مطلق خُدائ د تخت ښى لاس ته ناست دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28961, 'Hebrews 8:2', 'Hebrews', 8, 2, '&nbsp;هغه په هغه مقدس ځائ او هغه حقيقى خېمې کښې خادِم دے چې انسان نۀ بلکې مالِک خُدائ ودرولې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28962, 'Hebrews 8:3', 'Hebrews', 8, 3, '&nbsp;ځکه چې هر مشر اِمام د نذارانو او قربانو ورکولو دپاره مقرر دے، نو په کار دى چې زمونږ د اِمام سره هم د ورکولو دپاره څۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28963, 'Hebrews 8:4', 'Hebrews', 8, 4, '&nbsp;کۀ هغه په زمکه وے نو هغه به اِمام نۀ وے، ځکه چې نور اِمامان شته دے چې د شريعت په مطابق نذرانې پېش کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28964, 'Hebrews 8:5', 'Hebrews', 8, 5, '&nbsp;هغوئ چې په مقدس ځائ کښې عبادت کوى، نو هغه د هغه آسمانى عبادت نقل او تصوير دے. ځکه چې موسىٰ کله خېمه ودروله نو هغۀ ته دا هدايت ورکړے شُو چې، ”ګوره چې دا د هغې نقشې په مطابق جوړه کړې چې کومه ما درته په غرۀ باندې ښودلې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28965, 'Hebrews 8:6', 'Hebrews', 8, 6, '&nbsp;خو کوم خدمت چې عيسىٰ ته ورکړے شوے دے د زوړ لوظ نه د هغۀ مينځګړتوب ډېر زيات بهتر دے ځکه چې دا لوظ د ښۀ وعدو په بنياد شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28966, 'Hebrews 8:7', 'Hebrews', 8, 7, '&nbsp;ځکه چې کۀ اولنے لوظ بې‌نقصه وو نو بيا به د دوېم لوظ ضرورت نۀ پېښېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28967, 'Hebrews 8:8', 'Hebrews', 8, 8, '&nbsp;خو خُدائ پاک په خلقو کښې نقصان پېدا کړو او هغۀ وفرمائيل، ”مالِک فرمائى چې هغه وخت راروان دے چې زۀ به د اِسرائيل او د يهوداه د خلقو سره يو نوے لوظ وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28968, 'Hebrews 8:9', 'Hebrews', 8, 9, '&nbsp;دا به د هغه لوظ په شان نۀ وى کوم چې ما د هغوئ د پلار نيکۀ سره کړے وو کله چې ما هغوئ د لاس نه ونيول او د مِصر نه مې بهر وويستل، ځکه چې هغوئ ما سره کړے لوظ مات کړو. نو زۀ به هم د هغوئ څۀ پرواه نۀ کوم، مالِک فرمائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28969, 'Hebrews 8:10', 'Hebrews', 8, 10, '&nbsp;خو دا هغه نوے لوظ دے کوم به چې زۀ پس د دې نه د بنى اِسرائيلو د قبيلې سره وکړم، زۀ به خپل شريعت د هغوئ په مازغو کښې واچوم او د هغوئ په زړونو باندې به يې وليکم. زۀ به د هغوئ خُدائ پاک يم او هغوئ به زما خلق وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28970, 'Hebrews 8:11', 'Hebrews', 8, 11, '&nbsp;نور به د هغوئ نه يو کس هم خپل ګاونډى ته، او يا خپل ورور ته دا تعليم نۀ ورکوى چې مالِک خُدائ وپېژنه، ځکه چې د وړو نه واخله تر لويو پورې به هغوئ ټول ما پېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28971, 'Hebrews 8:12', 'Hebrews', 8, 12, '&nbsp;ځکه چې زۀ به د هغوئ په قصورونو رحم کوم او زۀ به نور د هغوئ ګناهونه هيڅکله نۀ يادوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28972, 'Hebrews 8:13', 'Hebrews', 8, 13, '&nbsp;کله چې خُدائ پاک د نوې لوظ خبرې وکړې نو اولنے يې منسوخ کړو، او کوم څيز چې منسوخ او زوړ شى هغه به زر فنا شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28973, 'Hebrews 9:1', 'Hebrews', 9, 1, '&nbsp;غرض دا چې په اولنى لوظ کښې هم د عبادت او د زمکنى عبادتخانې هدايت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28974, 'Hebrews 9:2', 'Hebrews', 9, 2, '&nbsp;نو يوه خېمه جوړه کړے شوه چې په اوله حِصه کښې ډيوټ، مېز او پېش کړے شوې روټۍ وې، چې ورته مقدس ځائ وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28975, 'Hebrews 9:3', 'Hebrews', 9, 3, '&nbsp;او د دوېمې پړدې نه وروستو هغه خېمه وه چې ورته زيات مقدس ځائ وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28976, 'Hebrews 9:4', 'Hebrews', 9, 4, '&nbsp;په هغې کښې د سرو زرو د خوشبو قربان‌ګاه او د لوظ صندوق وو چې په څلورو واړو طرفو يې سرۀ زر لګېدلى وُو. په دې کښې د من نه ډک يو د سرو زرو منګے، او د هارون زرغونه شوې امسا، او د کاڼو تختۍ چې پرې حُکمونه ليکلے شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28977, 'Hebrews 9:5', 'Hebrews', 9, 5, '&nbsp;د لوظ صندوق دپاسه د وزرو والا مخلوق جوړ شوى وُو چې د کفارې په تخت يې سورے کړے وو. مونږ اوس دا خبرې په نور تفصيل نۀ شُو بيانولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28978, 'Hebrews 9:6', 'Hebrews', 9, 6, '&nbsp;هر کله چې دا څيزونه دغه شان تيار کړے شول نو اولنۍ خېمې ته به اِمامان همېشه وخت په وخت ورننوتل او خپل د عبادت کار به يې کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28979, 'Hebrews 9:7', 'Hebrews', 9, 7, '&nbsp;خو دوېمې ته صرف مشر اِمام په ټول کال کښې يو ځل ورتلو، او بغېر د هغه وينې نه نۀ ورتلو چې هغۀ د ځان دپاره او د اُمت د ناپوهۍ د ګناهونو دپاره پېش کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28980, 'Hebrews 9:8', 'Hebrews', 9, 8, '&nbsp;په دې طريقه روحُ القُدس دا اِشاره کوى چې تر اوسه پورې زيات مقدس ځائ ته لار خلاصه شوې نۀ ده لا ترڅو چې پخوانۍ خېمه ولاړه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28981, 'Hebrews 9:9', 'Hebrews', 9, 9, '&nbsp;دا خېمه د موجوده زمانې يو مِثال دے او په دې کښې داسې نذرونه او قربانۍ ورکړے شوې چې په هغې د عبادت کوونکى ضمير پاک کولے نۀ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28982, 'Hebrews 9:10', 'Hebrews', 9, 10, '&nbsp;بلکې د هغوئ تعلق تش د خوراک څښاک او د پاکېدو تر مختلفو رسمونو پورې وو. دا احکامات تر هغې پورې مقرر دى ترڅو چې هغه وخت راشى چې هر څۀ صحيح کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28983, 'Hebrews 9:11', 'Hebrews', 9, 11, '&nbsp;خو کله چې مسيح د ښو څيزونو دپاره د مشر اِمام په طور راغے نو هغۀ په هغه لويه او کامله خېمه کښې خِدمت وکړو، چې انسان هغه خېمه نۀ ده جوړه کړې او نۀ هغه د دې دُنيا ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28984, 'Hebrews 9:12', 'Hebrews', 9, 12, '&nbsp;هغه يو ځل د ټولو دپاره زيات مقدس ځائ ته ننوتو، د چېلو او سخو وينو سره نه بلکې په خپله وينه يې دغه رنګ ابدى خلاصون زمونږ دپاره حاصل کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28985, 'Hebrews 9:13', 'Hebrews', 9, 13, '&nbsp;کۀ چرې د چېلو او غوَيانو په وينو نوستلو او د سخو په ايرو سره ناپاک خلق او د هغوئ بدنونه پاک کولے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28986, 'Hebrews 9:14', 'Hebrews', 9, 14, '&nbsp;نو د مسيح په وينه به لا نور څومره پاک شى، چا چې د ابدى روح په وسيله خپل ځان خُدائ پاک ته د بې‌عېبه قربانۍ په طور پېش کړو، چې هغه زمونږ ضمير شرارت اميز عملونو نه پاک کړى او چې مونږ د ژوندى خُدائ پاک عبادت وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28987, 'Hebrews 9:15', 'Hebrews', 9, 15, '&nbsp;په دې وجه مسيح د نوى لوظ مينځګړے دے. نو مقصد يې دا دے چې څوک خُدائ پاک بللى دى چې هغوئ هغه وعده کړے شوے ابدى ميراث حاصل کړى، ځکه چې کومه قربانى چې مسيح ورکړه هغې هغوئ د هغه اولنى لوظ د خطاګانو نه آزاد کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28988, 'Hebrews 9:16', 'Hebrews', 9, 16, '&nbsp;ځکه چرته چې وصيت دے هلته د وصيت کوونکى مرګ ثابتول هم ضرورى دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28989, 'Hebrews 9:17', 'Hebrews', 9, 17, '&nbsp;ځکه چې وصيت د مرګ نه پس جارى کيږى او ترڅو چې وصيت کوونکے ژوندے وى تر هغې دا وصيت نۀ جارى کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28990, 'Hebrews 9:18', 'Hebrews', 9, 18, '&nbsp;هم دغسې اولنے لوظ هم بغېر د وينې نه نۀ وو شوے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28991, 'Hebrews 9:19', 'Hebrews', 9, 19, '&nbsp;ځکه چې کله موسىٰ ټول اُمت ته د شريعت هر يو حُکم واورولو نو هغۀ د سخو او چېلو وينه د اوبو او سرې وړۍ او د ويلنې سره راواخسته او په خپله يې په هغه کِتاب او په ټول اُمت ونوستله،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28992, 'Hebrews 9:20', 'Hebrews', 9, 20, '&nbsp;او هغۀ وفرمائيل چې، ”دا د هغې لوظ وينه ده د کوم حُکم چې خُدائ پاک تاسو له درکړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28993, 'Hebrews 9:21', 'Hebrews', 9, 21, '&nbsp;او هم دغه شان هغۀ په خېمه کښې او په عبادت کښې استعمالېدونکو ټولو څيزونو باندې وينه ونوستله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28994, 'Hebrews 9:22', 'Hebrews', 9, 22, '&nbsp;په حقيقت کښې ټول څيزونه د شريعت په مطابق وينه پاکوى، او بغېر د وينې د تويولو نه د ګناهونو معافى نۀ کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28995, 'Hebrews 9:23', 'Hebrews', 9, 23, '&nbsp;د آسمانى څيزونو نمونې دپاره دا ضرورى وه چې هغه په دې طريقه پاک کړے شى، خو آسمانى څيزونو ته په خپله د دې نه د ښې قربانۍ ضرورت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28996, 'Hebrews 9:24', 'Hebrews', 9, 24, '&nbsp;ځکه چې مسيح هغه مقدس ځائ ته ورداخل نۀ شو چې په انسانى لاسونو جوړ وو چې د حقيقى عبادتخانې نقل وو، بلکې هغه په خپله په آسمان کښې داخل شو چې د خُدائ پاک په حضور کښې زمونږ دپاره حاضر شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28997, 'Hebrews 9:25', 'Hebrews', 9, 25, '&nbsp;هغه آسمان ته د خپل ځان د بار بار قربانۍ پېش کولو دپاره داخل نۀ شو څنګه چې مشر اِمام په زمکه باندې کال په کال هغه زيات مقدس ځائ ته د ځناورو د وينى سره ورننوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28998, 'Hebrews 9:26', 'Hebrews', 9, 26, '&nbsp;ځکه چې داسې به هغۀ د دُنيا د پېدايښت نه دا تکليف بيا بيا زغملو. خو داسې نۀ ده هغه اوس په يو ځل د زمانې په آخر د ټولو دپاره راښکاره شو چې د خپلې قربانۍ په وسيله ګناه ختمه کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28999, 'Hebrews 9:27', 'Hebrews', 9, 27, '&nbsp;او لکه چې څنګه د بنى آدم دپاره يو ځل مړ کېدل مقرر دى، او د هغې نه پس به عدالت ته وړاندې کيږى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29000, 'Hebrews 9:28', 'Hebrews', 9, 28, '&nbsp;نو مسيح هم هغه شان يو ځل د ډېرو خلقو د ګناه وړلو دپاره قربان شوے دے. نو دوېم ځل چې هغه ښکاره شى نو د ګناه د قربانۍ دپاره نه، بلکې د هغوئ د دپاره څوک چې په ډېره مينه د هغۀ اِنتظار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');